const response = $input.first().json;
const rawText = response.content[0].text;
const cleanedText = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const parsed = JSON.parse(cleanedText);
return parsed.map(item => ({ json: item }));

const raw = items[0].json;
const text = raw.content[0].text;
const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const parsed = JSON.parse(cleaned);
const inputItem = $('Loop Over Texts').item.json;

return [{
  json: {
    ID: String(inputItem.id || ""),
    Risk_Level: String(inputItem.risk_level || ""),
    Input_Text: String(inputItem.text || ""),
    Detected_Risk: String(parsed.risk_level || ""),
    Match: inputItem.risk_level === parsed.risk_level ? "CORRECT" : "MISMATCH",
    Violations_Found: Array.isArray(parsed.violations_found) ? parsed.violations_found.join(", ") : "",
    Flagged_Phrases: Array.isArray(parsed.flagged_phrases) ? parsed.flagged_phrases.join(", ") : "",
    Recommendation: String(parsed.recommendation || "")
  }
}];
